RBF_SIGMA = 0.01        # --sigma of the final comparison runs (run_q_learning default)
FIELD = 20.0            # Config::field_size, metres
DIAG = FIELD * np.sqrt(2.0)
ACTIONS = ["Hold", "Pass to F2", "Pass to F3"]  # enum Action: HOLD, PASS_F2, PASS_F3

# kFullFeatures order; (code name, readable name, unit, upper end of the normalisation range)
FEATURES = [
    ("D_F1_C", "Holder to centre", "m", DIAG / 2),
    ("D_F1_F2", "Holder to F2", "m", DIAG),
    ("D_F1_F3", "Holder to F3", "m", DIAG),
    ("D_F1_D1", "Holder to nearest taker", "m", DIAG),
    ("D_F1_D2", "Holder to other taker", "m", DIAG),
    ("D_F2_C", "F2 to centre", "m", DIAG / 2),
    ("D_F3_C", "F3 to centre", "m", DIAG / 2),
    ("D_D1_C", "Nearest taker to centre", "m", DIAG / 2),
    ("D_D2_C", "Other taker to centre", "m", DIAG / 2),
    ("MIN_D_F2_TAKER", "F2 to its closest taker", "m", DIAG),
    ("MIN_D_F3_TAKER", "F3 to its closest taker", "m", DIAG),
    ("MIN_ANG_F2", "Open angle of pass to F2", "°", 180.0),
    ("MIN_ANG_F3", "Open angle of pass to F3", "°", 180.0),
]
REDUCED = ["D_F1_D1", "D_F1_D2", "MIN_ANG_F2", "MIN_ANG_F3"]  # kReducedFeatures
XS = np.linspace(0.0, 1.0, 801)  # normalised variable values at which the curves are drawn


# ---- loading ------------------------------------------------------------------
def newest(root, dirs, prefix):
    files = []
    for d in dirs:
        files += glob.glob(os.path.join(root, d, prefix + "_*.csv"))
    if not files:
        raise FileNotFoundError(f"no {prefix}_*.csv in {dirs} under {root}")
    return max(files, key=lambda f: os.path.basename(f))  # names end in a timestamp


def benchmarks(root):
    path = newest(root, ["prev runs", "Final", "."], "benchmarks")
    return {name: secs.mean() for name, secs, _ in read_runs(path)}


def read_weights(path):
    with open(path) as f:
        dims = [int(v) for v in f.readline().split()]
        w = np.array([float(v) for v in f])
    return dims, w


def tc_curves(path):
    """f[i, x, a] for every state variable i, and visited[i, x, a]."""
    (n_sv, n_tilings, n_tiles, n_act), w = read_weights(path)
    w = w.reshape(n_sv, n_tilings, n_tiles + 1, n_act)
    width = 1.0 / n_tiles
    f = np.zeros((n_sv, len(XS), n_act))
    visited = np.ones((n_sv, len(XS), n_act), dtype=bool)
    for t in range(n_tilings):
        shift = t * width / n_tilings  # tile k covers [k*width - shift, (k+1)*width - shift)
        k = np.clip(np.floor((XS + shift) / width).astype(int), 0, n_tiles)
        f += w[:, t, k, :]
        visited &= w[:, t, k, :] != 0
    return f, visited


def rbf_curves(path, sigma=RBF_SIGMA):
    (n_sv, n_centres, n_act), w = read_weights(path)
    w = w.reshape(n_sv, n_centres, n_act)
    mids = (np.arange(n_centres) + 0.5) / n_centres
    phi = np.exp(-0.5 * ((XS[:, None] - mids[None, :]) / sigma) ** 2)  # x by centre
    f = np.einsum("xc,ica->ixa", phi, w)
    # visited: every centre within 2 sigma of x has been updated (otherwise untouched
    # zero weights pull the curve towards 0 at the edge of the visited range)
    reach = int(np.ceil(2 * sigma * n_centres))
    nearest = np.clip(np.floor(XS * n_centres).astype(int), 0, n_centres - 1)
    visited = np.ones((n_sv, len(XS), n_act), dtype=bool)
    for off in range(-reach, reach + 1):
        c = nearest + off
        inside = (c >= 0) & (c < n_centres)
        visited[:, inside, :] &= w[:, c[inside], :] != 0
    return f, visited


def learned(root, method, reduced=False):
    """Centred curves g[seed, i, x, a] (NaN where not visited by every seed)."""
    folder = f"cmp-{method}{'-reduced' if reduced else ''}-final"
    paths = sorted(glob.glob(os.path.join(root, "weights", folder, "seed-*.txt")),
                   key=lambda p: int(p.rsplit("-", 1)[1].split(".")[0]))
    if not paths:
        raise FileNotFoundError(f"no weights in {folder}")
    fn = tc_curves if method == "tc" else rbf_curves
    fs, vs = zip(*(fn(p) for p in paths))
    f, v = np.array(fs), np.array(vs)
    mask = v.all(axis=(0, 3))  # [i, x]: visited by every seed and for every action
    g = np.where(mask[None, :, :, None], f, np.nan)
    g = g - np.nanmean(g, axis=2, keepdims=True)
    return g, len(paths)


def effects(g):
    """Per seed and variable: (spread of the part shared by all actions,
    spread of the part that differs between actions), as standard deviations over x."""
    shared = np.nanmean(g, axis=3)                    # [seed, i, x]
    specific = g - shared[..., None]                  # [seed, i, x, a]
    s = np.nanstd(shared, axis=2)                     # [seed, i]
    d = np.sqrt(np.nanmean(np.nanvar(specific, axis=2), axis=2))
    return s, d


# ---- drawing ----------------------------------------------------------------------
def finish(fig, title, subtitle, path, right=0.95, bottom=0.165, left=0.085):
    """plot_results.finish with an adjustable left margin."""
    if MODE["ieee"]:
        if left > 0.15:  # effects figure: long variable names on the left, two-line panel titles
            save_ieee(fig, path, left=0.26, right=0.99, bottom=0.17, top=0.86)
        else:
            save_ieee(fig, path, right=0.72 if right < 0.9 else 0.98, bottom=0.2 if bottom < 0.2 else 0.24)
        return
    fig.text(0.015, 0.955, title, ha="left", va="top", fontsize=13, color=INK, fontweight="semibold")
    fig.text(0.015, 0.885, subtitle, ha="left", va="top", fontsize=9, color=INK2)
    fig.text(0.985, 0.01, "Visualization generated by an LLM (Claude, Anthropic)", ha="right", va="bottom",
             fontsize=7.5, color=MUTED)
    fig.subplots_adjust(left=left, right=right, top=0.78, bottom=bottom, wspace=0.08)
    fig.savefig(path, dpi=200)
    plt.close(fig)
    print("wrote", path)


def variable_panel(ax, g, i, feat, ylim, show_y):
    code, name, unit, hi = feat
    x = XS * hi
    for a, colour in enumerate(SERIES):
        y = g[:, i, :, a]
        ok = ~np.isnan(y).any(axis=0)
        ax.fill_between(x[ok], np.nanmin(y, axis=0)[ok], np.nanmax(y, axis=0)[ok], color=colour,
                        alpha=0.16, linewidth=0, zorder=2)
        ax.plot(x[ok], np.nanmean(y, axis=0)[ok], color=colour, linewidth=k(1.6), zorder=3)
    ax.axhline(0, color=MUTED, linewidth=k(0.6), zorder=1)
    ax.set_title(name, fontsize=k(9.5) if not MODE["ieee"] else 7, color=INK, loc="left", pad=3)
    ax.set_xlabel(f"{'degrees' if unit == '°' else 'metres'}  ·  {code}", fontsize=k(8), labelpad=1, color=INK2)
    ax.set_ylim(*ylim)
    ax.set_xlim(0, hi)
    ax.tick_params(labelsize=k(8), length=0)
    if not show_y:
        ax.set_yticklabels([])
    style_axes(ax)
    ax.grid(axis="x", color=GRID, linewidth=k(0.4))


def action_legend(ax, extra):
    ax.axis("off")
    for a, (label, colour) in enumerate(zip(ACTIONS, SERIES)):
        y = 0.92 - a * 0.13
        ax.plot([0.02, 0.14], [y, y], color=colour, linewidth=k(2.2), transform=ax.transAxes, clip_on=False)
        ax.text(0.17, y, label, transform=ax.transAxes, va="center", fontsize=k(9.5), color=INK)
    ax.text(0.02, 0.48, extra, transform=ax.transAxes, va="top", ha="left", fontsize=k(8), color=INK2,
            linespacing=1.45 if not MODE["ieee"] else 1.3, wrap=True)


NOTE = ("Line = mean of {n} seeds, band = lowest to highest seed. Higher = the keepers expect to keep the "
        "ball longer. Each curve is shifted to mean 0; compare slopes, not heights.")


def variable_figure(g, n_seeds, features, title, subtitle, path, ncols=4, row_labels=None):
    """One panel per variable. With row_labels, each row is one method and the legend goes on top."""
    n = len(features)
    compact = row_labels is not None
    nrows = int(np.ceil(n / ncols)) if compact else int(np.ceil((n + 1) / ncols))
    ieee = MODE["ieee"]
    head = (0.3 if compact else 0.05) if ieee else (1.55 if compact else 1.3)
    fig, axes = plt.subplots(nrows, ncols, figsize=(TEXT_W, 1.5 * nrows + head + (0.3 if compact else 0))
                             if ieee else (10, 2.35 * nrows + head))
    axes = np.atleast_2d(axes)
    lo, hi = np.nanmin(np.nanmin(g, axis=0)), np.nanmax(np.nanmax(g, axis=0))
    pad = 0.06 * (hi - lo)
    ylim = (lo - pad, hi + pad)
    for j, feat in enumerate(features):
        ax = axes[j // ncols, j % ncols]
        variable_panel(ax, g, j, feat, ylim, show_y=(j % ncols == 0))
        if j % ncols == 0:
            label = "Contribution to Q"
            if compact:
                label = f"{row_labels[j // ncols]}\n{label}"
            ax.set_ylabel(label, fontsize=k(8.5))
    if compact:
        handles = [plt.Line2D([], [], color=c, linewidth=k(2.2)) for c in SERIES]
        fig.legend(handles, ACTIONS, loc="upper left", ncol=3, fontsize=k(9.5),
                   bbox_to_anchor=(0.06, 1 - (0.02 if ieee else 0.78) / fig.get_figheight()))
        note = NOTE.format(n=n_seeds)
        if ieee:
            note = note.replace(" Higher", "\nHigher")
        fig.text(0.015, 0.03 if not ieee else 0.01, note, ha="left", va="bottom", fontsize=k(8), color=INK2)
    else:
        leg_ax = axes[n // ncols, n % ncols]
        action_legend(leg_ax, f"Line = mean of {n_seeds} seeds,\nband = lowest to highest seed.\n"
                              "Higher = the keepers expect to\nkeep the ball longer.\n"
                              "Each curve is shifted to mean 0;\ncompare slopes, not heights.")
    first_free = n if compact else n + 1
    for j in range(first_free, nrows * ncols):
        axes[j // ncols, j % ncols].axis("off")
    top = 1 - head / fig.get_figheight() + (0.0 if not compact else -0.1 / fig.get_figheight())
    if ieee:
        save_ieee(fig, path, left=0.09 if compact else 0.07, right=0.99, top=top,
                  bottom=0.2 if compact else 0.05, wspace=0.1, hspace=0.75 if not compact else 0.8)
        return
    fig.text(0.015, 1 - 0.18 / fig.get_figheight(), title, ha="left", va="top", fontsize=13, color=INK,
             fontweight="semibold")
    fig.text(0.015, 1 - 0.55 / fig.get_figheight(), subtitle, ha="left", va="top", fontsize=9, color=INK2)
    fig.text(0.985, 0.005, "Visualization generated by an LLM (Claude, Anthropic)", ha="right", va="bottom",
             fontsize=7.5, color=MUTED)
    fig.subplots_adjust(left=0.08 if compact else 0.07, right=0.98, top=top,
                        bottom=0.17 if compact else 0.07, wspace=0.08, hspace=0.62)
    fig.savefig(path, dpi=200)
    plt.close(fig)
    print("wrote", path)


def effects_figure(results, path):
    """results: [(label, colour, (shared[seed,i], specific[seed,i]))] over the 13 variables."""
    order = np.argsort([-(results[0][2][0][:, i].mean() + results[0][2][1][:, i].mean())
                        for i in range(len(FEATURES))])
    fig, axes = plt.subplots(1, 2, figsize=(TEXT_W, 3.4) if MODE["ieee"] else (10, 6.2), sharey=True,
                             sharex=True)
    y = np.arange(len(order))
    h = 0.36
    titles = ["How much it changes the value of the situation\n(part shared by all three actions)",
              "How much it changes which action is best\n(part that differs between actions)"]
    for p, ax in enumerate(axes):
        for m, (label, colour, eff) in enumerate(results):
            vals = eff[p][:, order]
            mean = vals.mean(axis=0)
            yy = y + (m - 0.5) * h
            ax.barh(yy, mean, height=h * 0.92, color=colour, label=label, zorder=3)
            ax.errorbar(mean, yy, xerr=[mean - vals.min(axis=0), vals.max(axis=0) - mean], fmt="none",
                        ecolor=INK2, elinewidth=k(0.8), capsize=0, zorder=4)
        ax.set_title(titles[p], fontsize=k(10), color=INK, loc="left")
        xl = "Standard deviation of the curve over visited values (Q units)"
        ax.set_xlabel(xl.replace("curve over", "curve\nover") if MODE["ieee"] else xl, fontsize=k(8.5))
        ax.grid(axis="x", color=GRID, linewidth=k(0.6))
        ax.set_axisbelow(True)
        ax.tick_params(length=0, labelsize=k(8.5))
        ax.spines["left"].set_visible(False)
    axes[0].set_yticks(y)
    axes[0].set_yticklabels([FEATURES[i][1] for i in order])
    axes[0].invert_yaxis()
    axes[0].legend(loc="lower right", fontsize=k(9))
    finish(fig, "Which state variables the learned values depend on",
           f"From the saved weights of the ε = {EPSILON} runs · bar = mean of 10 seeds, line = lowest to highest "
           "seed · visited values weighted equally",
           path, right=0.98, bottom=0.1, left=0.2)


# ---- main -----------------------------------------------------------------------------
def row(label, runs):
    e, l, sp, op = summarize(runs)
    reached = [s for s in sp if s is not None]
    return [label, len(e), f"{np.mean(e):.1f}", f"{min(e):.1f}", f"{max(e):.1f}", f"{np.mean(l):.1f}",
            f"{min(l):.1f}", f"{max(l):.1f}", int(np.median(reached)) if reached else "",
            len(sp) - len(reached), f"{np.mean(op):.1f}"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--results", default="results")
    ap.add_argument("--out", default=None)
    ap.add_argument("--ieee", action="store_true", help="print-size figures for a two-column IEEE paper")
    args = ap.parse_args()
    if args.ieee:
        set_ieee()
    if args.out is None:
        args.out = "results/figures/ieee" if args.ieee else "results/figures"
    os.makedirs(args.out, exist_ok=True)
    out = lambda name: os.path.join(args.out, name)
    eps_dirs = [".", "after-code-merge"]
    E = lambda prefix: read_runs(newest(args.results, eps_dirs, prefix))
    G = lambda prefix: read_runs(newest(args.results, ["precode-merge-results"], prefix))
    bench = benchmarks(args.results)

    runs = {k: E(f"cmp-{k}-final") for k in ("tc", "rbf", "nn")}
    runs_r = {k: E(f"cmp-{k}-reduced-final") for k in ("tc", "rbf", "nn")}
    runs_s = {k: E(f"cmp-{k}-sarsa-final") for k in ("tc", "rbf", "nn")}
    names = {"tc": "Tile coding", "rbf": "RBF", "nn": "Neural network"}
    n = len(runs["tc"])

    with open(out("summary_final.csv"), "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["condition", "seeds", "first5k_mean", "first5k_min", "first5k_max", "last5k_mean",
                    "last5k_min", "last5k_max", "episodes_to_30s_median", "seeds_never_reached",
                    "out_of_bounds_pct"])
        for feats, rs, gprefix in (("13 features", runs, ""), ("4 features", runs_r, "-reduced")):
            for k in ("tc", "rbf", "nn"):
                w.writerow(row(f"{names[k]}, {feats}, epsilon {EPSILON}", rs[k]))
            for k in ("tc", "rbf"):
                w.writerow(row(f"{names[k]}, {feats}, greedy run (epsilon 0)",
                               G(f"cmp-{k}{gprefix}-final")))
            ev = read_runs(newest(args.results, eps_dirs, f"cmp-nn{gprefix}-final-greedy-eval"))
            means = [s.mean() for _, s, _ in ev]
            w.writerow([f"Neural network, {feats}, greedy evaluation of saved weights", len(means), "", "", "",
                        f"{np.mean(means):.1f}", f"{min(means):.1f}", f"{max(means):.1f}", "", "", ""])
        for k in ("tc", "rbf", "nn"):
            w.writerow(row(f"{names[k]}, 13 features, Sarsa, epsilon {EPSILON}", runs_s[k]))
    print("wrote", out("summary_final.csv"))

    fig, ax = plt.subplots(figsize=figsize())
    learning_curves(ax, [(names[k], runs[k]) for k in ("tc", "rbf", "nn")], bench, band=True, ymax=40)
    finish(fig, f"Tile coding vs RBF vs neural network, with exploration (ε = {EPSILON})",
           f"13 state variables · γ = 0.99 · {n} seeds · band = range of seeds · all 3 keepers learn",
           out("fig10_final_curves.png"), right=0.79)

    fig, axes = plt.subplots(1, 2, figsize=figsize("full"), sharey=True)
    window_panels(fig, axes, [names[k] for k in ("tc", "rbf", "nn")], [runs[k] for k in ("tc", "rbf", "nn")],
                  bench, colours=SERIES)
    finish(fig, f"Early learning and final level (13 state variables, ε = {EPSILON})",
           f"Same runs as the learning curves · small dots = {n} seeds, large = mean",
           out("fig11_final_windows.png"), bottom=0.21)

    fig, ax = plt.subplots(figsize=figsize())
    learning_curves(ax, [(names[k], runs_r[k]) for k in ("tc", "rbf", "nn")], bench, band=True, ymax=40)
    finish(fig, f"Same comparison with the 4 reduced state variables (ε = {EPSILON})",
           f"D_F1_D1, D_F1_D2, MIN_ANG_F2, MIN_ANG_F3 · γ = 0.99 · {n} seeds · band = range of seeds",
           out("fig12_final_curves_reduced.png"), right=0.79)

    fig, ax = plt.subplots(figsize=figsize())
    learning_curves(ax, [(names[k], runs_s[k]) for k in ("tc", "rbf", "nn")], bench, band=True, ymax=40)
    finish(fig, f"Sarsa: tile coding vs RBF vs neural network (ε = {EPSILON})",
           f"13 state variables · γ = 0.99 · {len(runs_s['tc'])} seeds · band = range of seeds · all 3 keepers learn",
           out("fig17_sarsa_curves.png"), right=0.79)

    tc_g, n_tc = learned(args.results, "tc")
    rbf_g, n_rbf = learned(args.results, "rbf")
    variable_figure(tc_g, n_tc, FEATURES, "What tile coding learned about each state variable",
                    f"Learned contribution of each variable to Q(s, a), by action · ε = {EPSILON} runs · "
                    "20 tiles × 10 tilings · drawn only over values every seed visited",
                    out("fig13_tc_learned_by_variable.png"),
                    ncols=5 if MODE["ieee"] else 4)
    variable_figure(rbf_g, n_rbf, FEATURES, "What RBF learned about each state variable",
                    f"Learned contribution of each variable to Q(s, a), by action · ε = {EPSILON} runs · "
                    "200 centres, σ = 0.01 · drawn only over values every seed visited",
                    out("fig14_rbf_learned_by_variable.png"),
                    ncols=5 if MODE["ieee"] else 4)
    effects_figure([("Tile coding", SERIES[0], effects(tc_g)), ("RBF", SERIES[1], effects(rbf_g))],
                   out("fig15_variable_effects.png"))

    red = [f for f in FEATURES if f[0] in REDUCED]
    tcr_g, n_r = learned(args.results, "tc", reduced=True)
    rbfr_g, _ = learned(args.results, "rbf", reduced=True)
    both = np.concatenate([tcr_g, rbfr_g], axis=1)  # 8 panels: TC row, then RBF row
    variable_figure(both, n_r, red * 2, "What was learned with the 4 reduced state variables",
                    f"Top row: tile coding · bottom row: RBF · ε = {EPSILON} runs · drawn only over values "
                    "every seed visited", out("fig16_reduced_learned_by_variable.png"),
                    row_labels=["Tile coding", "RBF"])


if __name__ == "__main__":
    main()
